import{_ as a,o as t,c as r,an as o}from"./chunks/framework.GkUNdRcZ.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/faq.md","filePath":"getting-started/faq.md","lastUpdated":null}'),n={name:"getting-started/faq.md"};function s(i,e,c,h,d,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h1><h2 id="Why-is-there-no-renewal-or-AR-constructor?" tabindex="-1">Why is there no renewal or AR constructor? <a class="header-anchor" href="#Why-is-there-no-renewal-or-AR-constructor?" aria-label="Permalink to &quot;Why is there no renewal or AR constructor? {#Why-is-there-no-renewal-or-AR-constructor?}&quot;">​</a></h2><p>The operators describe steps, not models. A renewal process is <code>Recurrence(gi)</code> with the reproduction number as its gain, and an AR(p) process is <code>Recurrence(ρ)</code> with the innovations as <code>add</code>. Modelling packages such as <a href="https://composableturingidmodels.epiaware.org" target="_blank" rel="noreferrer">ComposableTuringIDModels.jl</a> name these and give them priors.</p><h2 id="Why-does-a-recurrence-kernel-start-at-lag-1-and-a-convolution-kernel-at-lag-0?" tabindex="-1">Why does a recurrence kernel start at lag 1 and a convolution kernel at lag 0? <a class="header-anchor" href="#Why-does-a-recurrence-kernel-start-at-lag-1-and-a-convolution-kernel-at-lag-0?" aria-label="Permalink to &quot;Why does a recurrence kernel start at lag 1 and a convolution kernel at lag 0? {#Why-does-a-recurrence-kernel-start-at-lag-1-and-a-convolution-kernel-at-lag-0?}&quot;">​</a></h2><p>A recurrence&#39;s value cannot depend on itself in the same step, so its first weight is on the previous value. A convolution can weight today&#39;s input, as a reporting delay of zero days does. Both are written as the quantity is usually written, so a generation interval or a delay goes in unchanged.</p><h2 id="How-do-I-get-intermediate-quantities?" tabindex="-1">How do I get intermediate quantities? <a class="header-anchor" href="#How-do-I-get-intermediate-quantities?" aria-label="Permalink to &quot;How do I get intermediate quantities? {#How-do-I-get-intermediate-quantities?}&quot;">​</a></h2><p>Operators return only their outputs. A step&#39;s value before the gain multiplies it is a convolution of the outputs, so <code>Convolution(vcat(0, g))</code> recomputes it. See the <a href="/previews/PR76/getting-started/api-overview#overview-time-series">time-series processes</a> on the API overview.</p><h2 id="Which-AD-backends-work?" tabindex="-1">Which AD backends work? <a class="header-anchor" href="#Which-AD-backends-work?" aria-label="Permalink to &quot;Which AD backends work? {#Which-AD-backends-work?}&quot;">​</a></h2><p>The AD tests run ForwardDiff, ReverseDiff, Mooncake and Enzyme. The <a href="/previews/PR76/benchmarks/ad-comparison#ad-comparison">AD comparison</a> page compares their gradient times.</p><h2 id="Why-is-my-history-padded-with-zeros?" tabindex="-1">Why is my history padded with zeros? <a class="header-anchor" href="#Why-is-my-history-padded-with-zeros?" aria-label="Permalink to &quot;Why is my history padded with zeros? {#Why-is-my-history-padded-with-zeros?}&quot;">​</a></h2><p>A history shorter than the kernel means there were no earlier values, so the missing lags count as zero.</p><h2 id="Recurrence-clashes-with-Lux" tabindex="-1"><code>Recurrence</code> clashes with Lux <a class="header-anchor" href="#Recurrence-clashes-with-Lux" aria-label="Permalink to &quot;`Recurrence` clashes with Lux {#Recurrence-clashes-with-Lux}&quot;">​</a></h2><p>Lux also exports a <code>Recurrence</code>. With both loaded by <code>using</code>, write <code>ComposableRecurrences.Recurrence</code> or import the one you need by name.</p>',13)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
